# Cases LOAD copied to the database
import json

cases = (spark.read.option("header", True).csv(f"{ROOT}/{SCHEMA_DIR}/S62aCase.csv")
         .select("id", "reference", "historicalReference").where("id IS NOT NULL")
         .dropDuplicates(["id"]).toPandas())
if cases.empty:
    raise ValueError(f"No cases in {SCHEMA_DIR}/S62aCase.csv, nothing to audit")

if LOADED_CASES:
    loaded = {str(c["id"] if isinstance(c, dict) else c).upper() for c in json.loads(LOADED_CASES)}
    if not loaded:
        raise ValueError("LOADED_CASES is empty: the database lookup after LOAD returned no cases")
else:
    loaded = None
print(f"Cases in this run: {len(cases)} | database lookup: {'yes, ' + str(len(loaded)) + ' ids' if loaded is not None else 'no'}")
